package org.apache.commons.lang3.time;

import org.junit.Test;
import org.junit.Assert;
import java.util.Calendar;
import java.util.TimeZone;

public class AgentBRT_Lang_38_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Set up a FastDateFormat instance with a forced time zone
        TimeZone timeZone = TimeZone.getTimeZone("GMT");
        FastDateFormat fastDateFormat = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss", timeZone);

        // Create a Calendar instance
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1, 0, 0, 0);
        calendar.setTimeZone(TimeZone.getTimeZone("PST")); // Different time zone

        // Format the calendar
        StringBuffer formatted = fastDateFormat.format(calendar, new StringBuffer());

        // The expected result should be in GMT, not PST
        String expected = "2023-01-01 08:00:00"; // PST to GMT conversion

        // Assert that the formatted result is as expected
        Assert.assertEquals("Formatted date is incorrect due to missing calendar.getTime() call.", expected, formatted.toString());
    }
}

